// The web panel of every mode (OnAir Web 3.9, docs/WEB-SCHEMA-3.9.md): the receiver's telemetry as one JSON object whose shape the browser
// learns from a schema, so one set of browser components (figures, tables, map, pictures, constellations, text) renders all modes.
// core/src/results/web_schema_gen.cpp is generated by tools/gen_web_schema.py from the telemetry structs; this header is the hand-written API.
#pragma once
#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>
namespace dect2 {
struct RxTelemetry;
namespace webschema {

// The full panel: {"standard":n,"common":{...the fields every mode has...},"fields":{...the mode's own struct...}}. maxBytes caps the result: over it
// the mode's own block is replaced by {"truncated":true} (the common block always fits). Returns false when the standard has no schema
// (the TV standards 0 .. 6 carry the common block and the rx_json details only; "fields" is then {}).
bool panelJson(const RxTelemetry& rx, std::string& out, size_t maxBytes = 256 * 1024);
// The mode's own block alone (the generated exporter); false: no schema for this standard
bool putModeFields(const RxTelemetry& rx, int standard, std::string& out);
// The schema of a standard's own block: a JSON array of {"n":name,"k":kind,"l":label,"u":unit?,"s":row struct?,"map":{...}?}; nullptr: none.
// Kinds: num, bool, text, list (numbers), lines (strings), table (rows of a struct), const (I/Q points), obj (a nested block), image (a PNG data URL).
const char* schemaJson(int standard);
const char* schemaStruct(int standard);          // the C++ struct behind it ("dect2::AdsbTelemetry"), nullptr: none
std::vector<int> schemaStandards();              // every standard with a schema
// The schema of the common block (the same for every mode)
const char* commonSchemaJson();
// Every schema in one object: {"<standard>":[...], ...} plus "common"
std::string allSchemasJson();

// The mode list as the desktop app shows it (generated from app/ui/mode_table.cpp): the rows and the group headings
struct WebModeRow {
    int family;            // the mode table's family number
    const char* name;
    int group;             // index into webModeGroups()
    const char* blurb;     // the one-line summary
    const char* sub;       // the sub-mode id ("ft8", "pocsag"), "" when the row is a family of its own
    int engineStd;         // Engine::setStandard() value (family + 2 from family 6 on; the TV families map to their own numbers)
    int standard;          // RxTelemetry::standard of this mode
    const char* member;    // the RxTelemetry member with its block, "" for the TV standards
};
const WebModeRow* webModeRows(int& n);
const char* const* webModeGroups(int& n);
std::string webModesJson();   // [{"family":..,"name":..,"group":..,"blurb":..,"sub":..,"standard":..,"schema":bool}], and the groups

namespace detail {
struct J {
    std::string& s;
    bool first = true;
    explicit J(std::string& str) : s(str) { s += '{'; }
    void key(const char* k) { if (!first) s += ','; first = false; s += '"'; s += k; s += "\":"; }
    void end() { s += '}'; }
};
struct Arr {
    std::string& s;
    bool first = true;
    explicit Arr(std::string& str) : s(str) { s += '['; }
    void next() { if (!first) s += ','; first = false; }
    void end() { s += ']'; }
};
void vnum(std::string& s, double v);                       // null for NaN / infinity, integers without a fraction
void vu64(std::string& s, unsigned long long v);
void vi64(std::string& s, long long v);
void vbool(std::string& s, bool v);
void vstr(std::string& s, const std::string& v, size_t maxBytes);   // valid UTF-8 only; cut at maxBytes on a character boundary
void vcplx(std::string& s, float re, float im);            // [re,im]
void vconst(std::string& s, const float* iq, size_t n, size_t maxPoints);   // interleaved I/Q -> a flat [i,q,i,q,...] array, subsampled to maxPoints
void vimage(std::string& s, const uint8_t* px, size_t n, int w, int h);     // "data:image/png;base64,..." (grey when n == w*h, RGB when 3*w*h) or null
std::vector<uint8_t> pngStored(const uint8_t* px, int w, int h, int channels);   // a PNG with stored deflate blocks (no zlib needed)
std::string base64(const uint8_t* p, size_t n);
} // namespace detail
} // namespace webschema
} // namespace dect2
